1	import React, { useEffect, useState } from 'react';
2	
3	// The dashboard feature owns its own state and data loading (no global store). It is a read-only home
4	// summary: how many clients and projects there are, how much money is still owed (the sum of
5	// every SENT invoice across all projects — drafts and paid invoices are excluded), and how many
