  useEffect(() => {
    void load();
  }, [invoiceId]);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const quantity = Number(qty);
    const price = Number(unitPrice);
    if (!description.trim() || !(quantity > 0) || !(price >= 0)) {
      setError('A description, a quantity and a price are required');
      return;
